const roleNames={owner:'Administrateur principal',admin:'Administrateur',editor:'Rédacteur',member:'Membre'};
function securityPassword(){return '<label>Votre mot de passe actuel<input name="current_password" type="password" required autocomplete="current-password"></label>';}
function roleSelect(role='admin',member=true){return `<select name="role">${Object.entries(roleNames).filter(([k])=>member||k!=='member').map(([k,v])=>`<option value="${k}" ${k===role?'selected':''}>${v}</option>`).join('')}</select>`;}
async function securityPage(tab){
 const token=pageToken;const data=await api('security');if(token!==pageToken)return;
 main.innerHTML=adminLayout(tab);const box=$('#admin-content');
 if(tab==='Utilisateurs'){
  if(state.user.role!=='owner'){box.innerHTML='<p>La gestion des utilisateurs est réservée aux administrateurs principaux.</p>';return;}
  const others=data.users.filter(u=>u.id!==state.user.id);
  box.innerHTML=`<h2>Gestion des utilisateurs</h2><section class="admin-order"><h3>Ajouter un administrateur ou un rédacteur</h3><form data-security="create-user"><div class="form-grid"><label>Nom complet<input name="name" required maxlength="160" autocomplete="off"></label><label>Adresse e-mail<input name="email" type="email" required autocomplete="off"></label><label>Rôle${roleSelect('admin',false)}</label><label>Mot de passe du nouvel utilisateur<input name="password" type="password" required minlength="10" maxlength="256" autocomplete="new-password"><small>10 caractères minimum.</small></label></div><p>Le compte sera actif immédiatement. Communiquez ses accès à l’utilisateur ; il pourra modifier son mot de passe dans Mon profil.</p><button class="btn">Enregistrer l’utilisateur</button><div class="feedback" role="status"></div></form></section>${others.map(u=>`<article class="admin-order"><h3>${esc(u.name)}</h3><p>${esc(u.email)} · ${roleNames[u.role]} · ${u.suspended?'Suspendu':'Actif'}</p><form data-security="user" data-id="${esc(u.id)}"><div class="form-grid"><label>Rôle${roleSelect(u.role)}</label><label>Accès<select name="suspended"><option value="false" ${!u.suspended?'selected':''}>Actif</option><option value="true" ${u.suspended?'selected':''}>Suspendu</option></select></label></div><button class="btn outline">Enregistrer les modifications</button><div class="feedback" role="status"></div></form></article>`).join('')||'<p>Aucun autre utilisateur pour le moment.</p>'}`;
 }else{
  box.innerHTML=`<h2>Mon profil et ma sécurité</h2><p>${roleNames[state.user.role]} · ${data.sessions} session(s) active(s)</p><form class="admin-order" data-security="profile"><h3>Mes informations</h3><div class="form-grid"><label>Nom complet<input name="name" value="${esc(state.user.name)}" required maxlength="160" autocomplete="name"></label><label>Adresse e-mail<input name="email" value="${esc(state.user.email)}" required type="email" autocomplete="email"></label>${securityPassword()}<label>Nouveau mot de passe (facultatif)<input name="new_password" type="password" minlength="10" maxlength="256" autocomplete="new-password"></label><label>Confirmer le nouveau mot de passe<input name="confirm_password" type="password" autocomplete="new-password"></label></div><p>Un changement de mot de passe déconnecte toutes vos sessions et invalide vos anciens codes de récupération.</p><button class="btn">Enregistrer mon profil</button><div class="feedback" role="status"></div></form><form class="admin-order" data-security="logout-all"><h3>Déconnecter toutes mes sessions</h3><p>Cette action vous déconnecte également de cet appareil.</p>${securityPassword()}<button class="btn outline">Déconnecter toutes les sessions</button><div class="feedback" role="status"></div></form><form class="admin-order" data-security="recovery-codes"><h3>Récupérer mon compte en cas d’oubli</h3><p>${data.recovery_remaining} code(s) de secours disponible(s). Générez vos codes et conservez-les dans un endroit sûr. Ils sont affichés une seule fois, valables un an. Leur renouvellement invalide les anciens codes.</p>${securityPassword()}<button class="btn outline">Générer mes codes de secours</button><div class="feedback" role="status"></div><div id="recovery-result"></div></form>`;
 }
 $$('[data-security]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();const b=$('button',f);b.disabled=true;try{const d=Object.fromEntries(new FormData(f));if(f.dataset.security==='profile'&&d.new_password!==d.confirm_password)throw Error('Les deux nouveaux mots de passe doivent être identiques.');if(f.dataset.id)d.id=f.dataset.id;if('suspended' in d)d.suspended=d.suspended==='true';const r=await api('security/'+f.dataset.security,d);if(f.elements.current_password)f.elements.current_password.value='';if(r.codes){$('#recovery-result').innerHTML=`<p>Copiez maintenant ces codes. Après une récupération, tous les codes sont invalidés : générez-en de nouveaux après connexion.</p><pre class="recovery-codes">${r.codes.map(esc).join('\n')}</pre>`;feedback(f,'Codes générés.');return;}await refresh();if(r.reconnect){location.hash='#/administration';await render();toast('Reconnectez-vous pour continuer.');}else{await render();toast('Modifications enregistrées.');}}catch(err){feedback(f,err.message,true);}finally{b.disabled=false;}});
}
function recoveryPage(params){
 main.innerHTML=banner('Récupération du compte')+`<section class="wrap section"><form id="recover-account" class="form-card"><h2>${params.get('token')?'Activer mon compte':'Choisir un nouveau mot de passe'}</h2><p>Utilisez votre lien d’invitation ou un code de secours généré dans votre profil. Aucun e-mail de récupération automatique n’est envoyé dans cette version locale.</p><label>Adresse e-mail<input name="email" type="email" required autocomplete="username"></label><label>Code d’invitation ou de secours<input name="token" value="${esc(params.get('token')||'')}" required autocomplete="off"></label><label>Nouveau mot de passe<input name="new_password" type="password" required minlength="10" maxlength="256" autocomplete="new-password"></label><label>Confirmer le mot de passe<input name="confirm_password" type="password" required autocomplete="new-password"></label><button class="btn">Enregistrer mon mot de passe</button><div class="feedback" role="status"></div></form></section>`;
 $('#recover-account').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=$('button',f);b.disabled=true;try{const data=Object.fromEntries(new FormData(f));if(data.new_password!==data.confirm_password)throw Error('Les mots de passe doivent être identiques.');await api('recover',data);f.reset();await refresh();location.hash='#/administration';toast('Mot de passe enregistré. Vous pouvez vous connecter.');}catch(err){feedback(f,err.message,true);}finally{b.disabled=false;}};
}
const accessWithoutRecovery=adminAccess;
adminAccess=function(){accessWithoutRecovery();if(!state.setup)$('#admin-access').insertAdjacentHTML('beforeend','<p><a class="text-link" href="#/recuperation">Mot de passe oublié ?</a></p>');};
